{
    "name": "smob",
    "version": "1.6.2",
    "description": "Zero dependency library to safe merge objects.",
    "type": "module",
    "main": "dist/index.cjs",
    "module": "dist/index.mjs",
    "types": "dist/index.d.mts",
    "exports": {
        "./package.json": "./package.json",
        ".": {
            "import": {
                "types": "./dist/index.d.mts",
                "default": "./dist/index.mjs"
            },
            "require": {
                "types": "./dist/index.d.cts",
                "default": "./dist/index.cjs"
            }
        }
    },
    "files": [
        "dist"
    ],
    "engines": {
        "node": ">=20.0.0"
    },
    "scripts": {
        "build:types": "tsc",
        "build:js": "tsdown",
        "build": "npm run build:types && npm run build:js",
        "lint": "eslint",
        "lint:fix": "npm run lint -- --fix",
        "test": "vitest --config test/vitest.config.ts --run",
        "test:coverage": "vitest --config test/vitest.config.ts --run --coverage",
        "prepare": "husky"
    },
    "author": {
        "name": "Peter Placzek",
        "email": "contact@tada5hi.net",
        "url": "https://github.com/tada5hi"
    },
    "license": "MIT",
    "keywords": [
        "object",
        "object-merge",
        "merge",
        "safe",
        "deep-merge",
        "merge-deep"
    ],
    "repository": {
        "type": "git",
        "url": "git+https://github.com/Tada5hi/smob.git"
    },
    "bugs": {
        "url": "https://github.com/Tada5hi/smob/issues"
    },
    "homepage": "https://github.com/Tada5hi/smob#readme",
    "publishConfig": {
        "access": "public"
    },
    "devDependencies": {
        "@tada5hi/commitlint-config": "^1.3.1",
        "@tada5hi/eslint-config": "^2.3.0",
        "@tada5hi/tsconfig": "^0.7.2",
        "@vitest/coverage-v8": "^4.1.5",
        "eslint": "^10.3.0",
        "husky": "^9.1.7",
        "tsdown": "^0.22.0",
        "typescript": "^5.9.3",
        "typescript-eslint": "^8.59.2",
        "vitest": "^4.1.5"
    }
}
